// รับข้อมูล catalog จาก Admin Panel
const body = $input.first().json.body || $input.first().json;
const catalog = body.catalog || [];

if (catalog.length === 0) {
  return [{ json: { sql: 'DELETE FROM bike_catalog;', count: 0 } }];
}

// สร้าง SQL: DELETE ทั้งหมด แล้ว INSERT ใหม่
const esc = (s) => String(s||'').replace(/'/g, "''");

const values = catalog.map((c, i) => {
  const bt   = esc(c.bike_type);
  const mn   = esc(c.model_name);
  const vn   = esc(c.variant_name || '');
  const cc   = parseInt(c.engine_cc) || 0;
  const tr   = esc(c.transmission || 'Automatic');
  const ia   = (c.is_active !== false && c.is_active !== 0) ? 'true' : 'false';
  const so   = parseInt(c.sort_order) || i;
  const note = esc(c.note || '');
  return `('${bt}','${mn}','${vn}',${cc},'${tr}',${ia},${so},'${note}',NOW())`;
});

const sql = `DELETE FROM bike_catalog;\nINSERT INTO bike_catalog (bike_type,model_name,variant_name,engine_cc,transmission,is_active,sort_order,note,updated_at) VALUES ${values.join(',')};`;

return [{ json: { sql, count: catalog.length } }];
